4.1 베르누이 모집단의 표본추출
\[
\begin{align}
f_X(x)=\begin{cases}
p \,\,\, &\mathrm{if} \,\,\, x=1, \,\,\, p\in[0,1] \\
1-p \,\,\, &\mathrm{if} \,\,\, x=0, \,\,\, p\in[0,1]\\
0 \,\,\, &\mathrm{otherwise}
\end{cases}
\end{align}
\]
\[
I_A(a)=\begin{cases}
1 \,\,\, \mathrm{if} \,\,\, a\in A \\
0 \,\,\, \mathrm{otherwise}
\end{cases}
\]
\[
f_{X}(x)=p^{x}(1-p)^{1-x},\,\,\, {\mathrm{for}} \,\,\, x=0,1 \,\,\,{\mathrm{and}}\,\,\, p\in[0,1]
\]
\[
f_{X}(x)=p^{x}(1-p)^{1-x}I_{\{0,1\}}(x)I_{[0,1]}(p)
\]
\[
\mu_{X}=p\,\,\, \mathrm{and}\,\,\,\sigma_{X}^{2}=p(1-p)
\]

5.1 누적분포함수(CDF)
\[
F_{X}(x)=P(X\leq x)
\]
\[
F(x)=\begin{cases}
{0}&{x\in(-\infty,0)}\\ {{\frac{1}{2}}}&{x\in[0,1)}\\ {{\frac{1}{8}}}&{x\in[2,3)}\\ {1}&{x\in[3,\infty)}
\end{cases}
\]
\[
F(t)=\begin{cases}
{{0}}&{{t\lt 0}}\\ {{1-e^{-\lambda t}}}&{{t\geq 0}}
\end{cases}
\]
\[
P(a\leq X\leq b)=1=\lambda(b-a)\Longrightarrow\lambda=\frac{1}{b-a}
\]
\[
F(x)=P(X\leq x)=P(a\leq X\leq x)=\begin{cases}
{0}&{x\lt a}\\ {\frac{x-a}{b-a}}&{x\in[a,b]}\\ {1}&{x\gt b}
\end{cases}
\]
